const input = $input.first().json;
const action = input.action;

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pgHeaders = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY };

// Vexa splits its API into two scopes with separate keys. A bot key is rejected on
// transcript endpoints and a transcription key is rejected on bot endpoints, both with
// HTTP 403 "Insufficient scope for this endpoint". Verified against the live API.
const allCreds = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.vexa-meetings&select=cred_key,cred_value',
  headers: pgHeaders
});
const creds = {};
for (const c of (allCreds || [])) creds[c.cred_key] = c.cred_value;

const apiKey = creds.vexa_api_key;
const txKey = creds.vexa_tx_key;

const MISSING = 'Vexa needs TWO separate keys since v2. Missing: KEYS. '
  + 'Add them with add_credential: "vexa_api_key" is the bot key (starts with vxa_bot_) and drives '
  + 'deploy_meeting_bot, list_bots and stop_bot. "vexa_tx_key" is the transcription key (starts with '
  + 'vxa_tx_) and drives get_transcript and share_transcript. Both are in the Vexa dashboard under API keys.';
const missing = [];
if (!apiKey) missing.push('vexa_api_key');
if (!txKey) missing.push('vexa_tx_key');
if (missing.length) {
  return [{ json: { error: MISSING.replace('KEYS', missing.join(' and ')) } }];
}

const API_BASE = String(creds.vexa_url || 'https://api.cloud.vexa.ai').replace(/\/+$/, '');
const apiHeaders = { 'X-API-Key': apiKey, 'Content-Type': 'application/json' };
const txHeaders = { 'X-API-Key': txKey, 'Content-Type': 'application/json' };

// Turns an httpRequest failure into a message that names the key at fault. A 403 here is
// almost always the wrong scope rather than an invalid key.
function apiError(err, scope) {
  const msg = String((err && err.message) || err || '');
  const key = scope === 'bot' ? 'vexa_api_key (vxa_bot_...)' : 'vexa_tx_key (vxa_tx_...)';
  if (msg.indexOf('403') >= 0) {
    return 'Vexa refused the request with 403 (insufficient scope). This endpoint needs ' + key
      + '. Check that the right key is stored under that name.';
  }
  if (msg.indexOf('401') >= 0) {
    return 'Vexa rejected the key with 401. Check ' + key + '.';
  }
  return msg;
}

function parseMeetingUrl(url) {
  if (!url) return null;
  url = String(url).trim();

  // Google Meet: https://meet.google.com/abc-defg-hij
  const gmeetMatch = url.match(/meet\.google\.com\/([a-z]{3}-[a-z]{4}-[a-z]{3})/i);
  if (gmeetMatch) return { platform: 'google_meet', native_meeting_id: gmeetMatch[1] };

  // Microsoft Teams: https://teams.live.com/meet/1234567890123?p=XYZ
  const teamsMatch = url.match(/teams\.(?:live|microsoft)\.com\/(?:meet|l\/meetup-join)\/([^?&#]+)/);
  if (teamsMatch) {
    let meetingId = teamsMatch[1];
    try { meetingId = decodeURIComponent(meetingId); } catch (e) { /* keep raw */ }
    if (meetingId.slice(-2) === '/0') meetingId = meetingId.slice(0, -2);
    const passcodeMatch = url.match(/[?&](?:p|passcode)=([^&#]+)/);
    return { platform: 'teams', native_meeting_id: meetingId, passcode: passcodeMatch ? passcodeMatch[1] : undefined };
  }

  // Zoom: https://us05web.zoom.us/j/12345678901?pwd=...
  const zoomMatch = url.match(/zoom\.us\/j\/(\d+)/);
  if (zoomMatch) {
    const pwdMatch = url.match(/[?&]pwd=([^&#]+)/);
    return { platform: 'zoom', native_meeting_id: zoomMatch[1], passcode: pwdMatch ? pwdMatch[1] : undefined };
  }

  return null;
}

// Resolves platform + meeting id from either explicit params or a full URL.
function resolveMeeting(inp) {
  let platform = inp.platform;
  let meetingId = inp.meeting_id;
  if (inp.meeting_url && (!platform || !meetingId)) {
    const parsed = parseMeetingUrl(inp.meeting_url);
    if (parsed) {
      platform = parsed.platform;
      meetingId = parsed.native_meeting_id;
    }
  }
  return { platform: platform, meetingId: meetingId };
}

// ── ACTION: deploy_meeting_bot ──
if (action === 'deploy_meeting_bot') {
  const meetingUrl = input.meeting_url;
  if (!meetingUrl) {
    return [{ json: { error: 'Parameter "meeting_url" is required. Provide a Google Meet, Teams, or Zoom URL.' } }];
  }

  const parsed = parseMeetingUrl(meetingUrl);
  if (!parsed) {
    return [{ json: { error: 'Could not parse meeting URL. Supported: Google Meet (meet.google.com/xxx-xxxx-xxx), Microsoft Teams (teams.live.com/meet/... or teams.microsoft.com/meet/...), Zoom (zoom.us/j/...)' } }];
  }

  if (!parsed.passcode && input.passcode) parsed.passcode = String(input.passcode).trim();

  if (parsed.platform === 'teams' && !parsed.passcode) {
    return [{ json: { error: 'Teams meeting without a passcode. Microsoft refuses the bot in that case, '
      + 'so NO bot was deployed. Use the FULL invitation link (it ends in "?p=...") or give meeting ID and '
      + 'passcode separately, then the link https://teams.microsoft.com/meet/MEETING_ID?p=PASSCODE can be built.' } }];
  }

  const body = {
    platform: parsed.platform,
    native_meeting_id: parsed.native_meeting_id
  };
  if (parsed.passcode) body.passcode = parsed.passcode;

  // Vexa only picks up the passcode from the full meeting_url. A separate passcode field is
  // silently ignored, which is why a Teams bot appears to be deployed and then never joins.
  // google_meet is left alone, it works without a passcode.
  if (parsed.platform !== 'google_meet') {
    let joinUrl = meetingUrl;
    const hasPasscodeInUrl = /[?&](?:p|passcode|pwd)=/.test(meetingUrl);
    if (parsed.platform === 'teams' && !hasPasscodeInUrl && parsed.passcode) {
      joinUrl = 'https://teams.microsoft.com/meet/' + parsed.native_meeting_id + '?p=' + parsed.passcode;
    }
    body.meeting_url = joinUrl;
  }

  if (input.language) body.language = String(input.language).trim();
  body.bot_name = input.bot_name || 'Meeting Notetaker';
  if (input.recording !== undefined && input.recording !== '') {
    body.recording_enabled = input.recording === true || input.recording === 'true';
  }

  try {
    const data = await helpers.httpRequest({
      method: 'POST',
      url: API_BASE + '/bots',
      headers: apiHeaders,
      body: JSON.stringify(body)
    });

    // The meeting ID of a Teams or Zoom room is stable, so a recurring meeting produces
    // several Vexa runs under the same ID. /transcripts/{platform}/{id} then silently
    // returns the NEWEST run. Capture Vexa's internal run ID now, while the run we just
    // started is the newest one, so get_transcript can prove later which run it got.
    let runId = data.id || null;
    if (!runId) {
      try {
        const list = await helpers.httpRequest({
          method: 'GET',
          url: API_BASE + '/meetings',
          headers: { 'X-API-Key': txKey }
        });
        const mine = (list.meetings || [])
          .filter(function (x) {
            return x.platform === parsed.platform && String(x.native_meeting_id) === String(parsed.native_meeting_id);
          })
          .sort(function (a, b) {
            return Number(b.id || 0) - Number(a.id || 0);
          });
        if (mine.length) runId = mine[0].id;
      } catch (e) { /* identity stays unknown, handled below */ }
    }

    let result = 'Bot deployed successfully!\n';
    result += '  Platform: ' + parsed.platform + '\n';
    result += '  Meeting ID: ' + parsed.native_meeting_id + '\n';
    result += '  Status: ' + (data.status || 'requested') + '\n';
    if (data.constructed_meeting_url) result += '  URL: ' + data.constructed_meeting_url + '\n';
    if (runId) result += '  Vexa run ID: ' + runId + '\n';
    result += '\nThe bot will join the meeting shortly and start transcribing.\n';
    if (runId) {
      result += '\nIMPORTANT - remember the Vexa run ID ' + runId + ' for this meeting. To fetch the '
        + 'transcript later, call get_transcript with platform="' + parsed.platform + '", meeting_id="'
        + parsed.native_meeting_id + '" AND vexa_run_id="' + runId + '". Without the run ID the tool '
        + 'cannot prove which run it received, because a recurring meeting reuses the same meeting ID.';
    } else {
      result += '\nWARNING: Vexa did not return a run ID for this deployment, so a later transcript '
        + 'cannot be proven to belong to this run. Check the date the transcript reports before using it.';
    }

    return [{ json: { result } }];
  } catch (err) {
    return [{ json: { error: 'Failed to deploy bot: ' + apiError(err, 'bot') } }];
  }

// ── ACTION: get_transcript ──
} else if (action === 'get_transcript') {
  const m = resolveMeeting(input);
  if (!m.platform || !m.meetingId) {
    return [{ json: { error: 'Parameters "platform" (google_meet/teams/zoom) and "meeting_id" are required, or pass "meeting_url" instead.' } }];
  }

  let data;
  try {
    data = await helpers.httpRequest({
      method: 'GET',
      url: API_BASE + '/transcripts/' + encodeURIComponent(m.platform) + '/' + encodeURIComponent(m.meetingId),
      headers: { 'X-API-Key': txKey }
    });
  } catch (err) {
    return [{ json: { error: 'Failed to fetch transcript: ' + apiError(err, 'tx') } }];
  }

  // IDENTITY GUARD. Vexa addresses transcripts by the meeting room ID, which a recurring
  // meeting reuses, and it returns the NEWEST run for that room without saying so. Verified
  // against the live API: no query parameter and no alternative endpoint can reach an older
  // run. So the only safe behaviour is to prove the run or hand back nothing.
  const gotRun = data.id !== undefined && data.id !== null ? String(data.id) : '';
  const wantRun = input.vexa_run_id ? String(input.vexa_run_id).trim() : '';

  if (wantRun && gotRun && wantRun !== gotRun) {
    return [{ json: { error:
      'REFUSED: this is not the requested meeting. You asked for Vexa run ' + wantRun
      + ', but Vexa returned run ' + gotRun + ' (started ' + (data.start_time || 'unknown')
      + ', status ' + (data.status || 'unknown') + '). Meeting ID ' + m.meetingId + ' belongs to a '
      + 'recurring meeting room, and Vexa only ever serves the most recent run for a room. The run '
      + 'you asked for can no longer be retrieved through the API. NO transcript is returned, because '
      + 'returning a different meeting would be worse than returning nothing. Tell the user plainly '
      + 'that the transcript of that specific session is not retrievable.' } }];
  }

  const identity = 'Vexa run ID: ' + (gotRun || 'unknown') + '\n'
    + 'This transcript belongs to the meeting that started: ' + (data.start_time || 'unknown') + '\n';
  const unproven = !wantRun
    ? 'WARNING: no vexa_run_id was supplied, so this transcript is NOT proven to be the meeting you '
      + 'have in mind. Vexa serves the most recent run for meeting ID ' + m.meetingId + ', and a '
      + 'recurring meeting reuses that ID. State the start date above to the user before using this '
      + 'transcript, and do not assume it is a particular session.\n'
    : '';

  const segments = data.segments || [];
  if (segments.length === 0) {
    let result = 'No transcript segments available in the run Vexa returned.\n' + identity;
    if (data.status) result += 'Status of that run: ' + data.status + '.\n';
    result += '\nThis means one of three things: the bot is still joining, the meeting produced no '
      + 'audio, or a LATER bot run into the same meeting room failed and is now masking an earlier '
      + 'successful recording. Vexa cannot serve the earlier run. Do not report this as "the meeting '
      + 'had no content" without saying which run was checked.';
    return [{ json: { result } }];
  }

  const UNKNOWN = '(unknown speaker)';
  const GAP_SECONDS = 12;

  function isRealName(n) {
    if (!n) return false;
    if (n === 'Speaker' || n === 'Unknown') return false;
    return String(n).indexOf('seg_') !== 0;
  }
  function clockOf(s) {
    const t = s.absolute_start_time;
    return t ? String(t).substring(11, 19) : '';
  }
  function toSeconds(hhmm) {
    if (!hhmm) return null;
    const p = String(hhmm).trim().split(':');
    const h = parseInt(p[0], 10);
    if (isNaN(h)) return null;
    const mi = p.length > 1 ? parseInt(p[1], 10) || 0 : 0;
    const se = p.length > 2 ? parseInt(p[2], 10) || 0 : 0;
    return h * 3600 + mi * 60 + se;
  }

  const fromSec = toSeconds(input.from_time);
  const toSec = toSeconds(input.to_time);

  // 1) optional time window, evaluated on the wall clock of each segment
  const kept = [];
  for (const s of segments) {
    const txt = String(s.text || '').trim();
    if (!txt) continue;
    const c = clockOf(s);
    if ((fromSec !== null || toSec !== null) && c) {
      const cs = toSeconds(c);
      if (fromSec !== null && cs < fromSec) continue;
      if (toSec !== null && cs > toSec) continue;
    }
    kept.push(s);
  }

  if (kept.length === 0) {
    return [{ json: { result: 'No transcript segments in the requested time window. Call get_transcript without from_time and to_time to see the full range first.' } }];
  }

  // 2) consecutive segments of the same speaker become one block. Segments without a speaker
  // are NEVER folded into the previous one, that would invent an attribution.
  const blocks = [];
  for (const s of kept) {
    const who = isRealName(s.speaker) ? s.speaker : UNKNOWN;
    const start = s.start || 0;
    const last = blocks.length ? blocks[blocks.length - 1] : null;
    if (last && last.who === who && (start - last.end) <= GAP_SECONDS) {
      last.text += ' ' + String(s.text || '').trim();
      last.end = s.end || start;
    } else {
      blocks.push({ who: who, time: clockOf(s), text: String(s.text || '').trim(), end: s.end || start });
    }
  }

  const names = [];
  let unknownCount = 0;
  for (const b of blocks) {
    if (b.who === UNKNOWN) { unknownCount++; continue; }
    if (names.indexOf(b.who) < 0) names.push(b.who);
  }

  const firstClock = clockOf(kept[0]);
  const lastClock = clockOf(kept[kept.length - 1]);

  let result = 'Transcript for ' + m.platform + ' meeting ' + m.meetingId + '\n';
  result += identity;
  if (unproven) result += unproven;
  result += 'Status: ' + (data.status || 'unknown') + '\n';
  if (data.end_time) result += 'Ended: ' + data.end_time + '\n';
  else result += 'Ended: not yet, this meeting is still running\n';
  result += 'Time range in this output: ' + firstClock + ' to ' + lastClock + '\n';
  result += 'Speakers identified: ' + (names.length ? names.join(', ') : 'none') + '\n';
  if (unknownCount) {
    result += 'NOTE: ' + unknownCount + ' passages could not be attributed to a speaker and are marked "'
      + UNKNOWN + '". Do NOT guess who said them. Attribute a name only if the person identifies '
      + 'themselves in the text.\n';
  }
  if (!names.length) {
    result += 'NOTE: this meeting has NO speaker names at all. Every line is a separate turn with a '
      + 'timestamp, so a change of speaker is visible but not who is speaking. Do not assign names in '
      + 'the minutes unless people name themselves.\n';
  }
  result += '\n--- Transcript ---\n\n';

  for (const b of blocks) {
    result += (b.time ? '[' + b.time + '] ' : '') + b.who + ': ' + b.text + '\n';
  }

  // 3) guard against flooding the model context. The hint has to be actionable, so it names
  // the parameters and the real time range of the meeting.
  const MAXLEN = 60000;
  if (result.length > MAXLEN) {
    result = result.substring(0, MAXLEN)
      + '\n\n[... truncated. Call get_transcript again with from_time and to_time (format HH:MM) to '
      + 'fetch a specific part. This meeting runs from ' + firstClock + ' to ' + lastClock + '.]';
  }

  return [{ json: { result } }];

// ── ACTION: share_transcript ──
} else if (action === 'share_transcript') {
  const m = resolveMeeting(input);
  if (!m.platform || !m.meetingId) {
    return [{ json: { error: 'Parameters "platform" and "meeting_id" are required, or pass "meeting_url" instead.' } }];
  }

  try {
    const data = await helpers.httpRequest({
      method: 'POST',
      url: API_BASE + '/transcripts/' + encodeURIComponent(m.platform) + '/' + encodeURIComponent(m.meetingId) + '/share',
      headers: txHeaders
    });

    let result = 'Shareable transcript link created:\n';
    if (data.url) result += '  URL: ' + data.url + '\n';
    if (data.expires_at) result += '  Expires: ' + data.expires_at + '\n';
    if (data.expires_in_seconds) result += '  Valid for: ' + Math.round(data.expires_in_seconds / 60) + ' minutes\n';
    result += '\nAnyone with this link can read the transcript until it expires.';

    return [{ json: { result } }];
  } catch (err) {
    return [{ json: { error: 'Failed to create share link: ' + apiError(err, 'tx') } }];
  }

// ── ACTION: list_bots ──
} else if (action === 'list_bots') {
  try {
    const data = await helpers.httpRequest({
      method: 'GET',
      url: API_BASE + '/bots/status',
      headers: { 'X-API-Key': apiKey }
    });

    const bots = data.running_bots || data.running || [];
    if (bots.length === 0) {
      return [{ json: { result: 'No bots currently running.' } }];
    }

    let result = 'Running bots (' + bots.length + '):\n\n';
    for (const bot of bots) {
      result += '- ' + (bot.platform || 'unknown') + ' / ' + (bot.native_meeting_id || bot.meeting_id_from_name || '?') + '\n';
      result += '  Status: ' + (bot.normalized_status || bot.status || 'unknown') + '\n';
      if (bot.created_at) result += '  Started: ' + bot.created_at + '\n';
      result += '\n';
    }

    return [{ json: { result } }];
  } catch (err) {
    return [{ json: { error: 'Failed to list bots: ' + apiError(err, 'bot') } }];
  }

// ── ACTION: stop_bot ──
} else if (action === 'stop_bot') {
  const m = resolveMeeting(input);
  if (!m.platform || !m.meetingId) {
    return [{ json: { error: 'Parameters "platform" and "meeting_id" are required, or pass "meeting_url" instead.' } }];
  }

  try {
    await helpers.httpRequest({
      method: 'DELETE',
      url: API_BASE + '/bots/' + encodeURIComponent(m.platform) + '/' + encodeURIComponent(m.meetingId),
      headers: { 'X-API-Key': apiKey }
    });

    return [{ json: { result: 'Bot stop request accepted. The bot will leave the meeting shortly.' } }];
  } catch (err) {
    return [{ json: { error: 'Failed to stop bot: ' + apiError(err, 'bot') } }];
  }

} else {
  return [{ json: { error: 'Unknown action: "' + action + '". Available: deploy_meeting_bot, get_transcript, share_transcript, list_bots, stop_bot.' } }];
}
